1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { AudioManager } from '../systems/AudioManager';
4	
5	/**
6	 * BootScene — the first, minimal scene. Applies the persisted mute preference to
7	 * the sound manager and hands straight off to PreloadScene. (Scale/physics are
8	 * configured once in main.ts; nothing to load for the boot screen itself.)
9	 */
10	export class BootScene extends Phaser.Scene {
11	  constructor() {
12	    super({ key: SceneKey.Boot });
13	  }
14	
15	  create(): void {
16	    AudioManager.apply(this.sound);
17	    this.scene.start(SceneKey.Preload);
18	  }
19	}
