1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import {
4	  GAME_WIDTH,
5	  GAME_HEIGHT,
6	  GROUND_TOP_Y,
7	  HERO_X,
8	  MAX_HP,
9	  SCORE_SURVIVAL_PER_S,
10	  TARGET_DURATION_S,
11	} from '../config/gameConfig';
12	import { KEYS } from '../config/assetManifest';
13	import { t } from '../i18n/strings';
14	import { track, type FinishGameParams } from '../analytics/track';
15	import { createButton } from '../ui/Button';
16	import { HeroDog } from '../entities/HeroDog';
17	
18	/**
19	 * GameScene — Phase 1 PLACEHOLDER run screen. It renders the park backdrop, the
20	 * hero, and a HUD, fires `start_game` on entry, and exposes TEMPORARY debug
21	 * controls (on-screen Win/Lose buttons + W/L keys) that end the run, fire
22	 * `finish_game`, and hand a result to ResultsScene. No real gameplay/physics yet
23	 * — this exists purely to make the flow navigable end-to-end.
24	 */
25	export class GameScene extends Phaser.Scene {
26	  private hero!: HeroDog;
27	  private scoreText!: Phaser.GameObjects.Text;
28	  private progressFill!: Phaser.GameObjects.Rectangle;
29	
30	  private elapsedMs = 0;
31	  private score = 0;
32	  private finished = false;
33	
34	  constructor() {
35	    super({ key: SceneKey.Game });
36	  }
37	
38	  create(): void {
39	    this.elapsedMs = 0;
40	    this.score = 0;
41	    this.finished = false;
42	
43	    this.buildBackground();
44	    this.hero = new HeroDog(this, HERO_X, GROUND_TOP_Y);
45	    this.buildHud();
46	    this.buildDebugFinishControls();
47	
48	    // A round has begun.
49	    track('start_game');
50	
51	    // Placeholder input: cosmetic hop only (real jump physics is Phase 2).
52	    this.input.on(Phaser.Input.Events.POINTER_DOWN, () => this.hero.nudgeJump());
53	    const space = this.input.keyboard?.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);
54	    space?.on('down', () => this.hero.nudgeJump());
55	
56	    // Per-frame accumulator for active-play time (spec §7.2). Wired via the
57	    // scene UPDATE event so a later phase can freeze it during pause cleanly.
58	    this.events.on(Phaser.Scenes.Events.UPDATE, this.onUpdate, this);
59	    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
60	      this.events.off(Phaser.Scenes.Events.UPDATE, this.onUpdate, this);
61	    });
62	  }
63	
64	  private buildBackground(): void {
65	    const cx = GAME_WIDTH / 2;
66	    this.add.image(cx, GAME_HEIGHT / 2, KEYS.park_bg_far);
67	    this.add.image(cx, GROUND_TOP_Y, KEYS.park_bg_near).setOrigin(0.5, 1);
68	    this.add
69	      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, KEYS.ground_tile)
70	      .setOrigin(0.5, 0);
71	    this.add.image(cx, GAME_HEIGHT, KEYS.park_fg_grass).setOrigin(0.5, 1);
72	  }
73	
74	  private buildHud(): void {
75	    // Score (top-left).
76	    this.scoreText = this.add.text(24, 18, `${t('hud_score')}: 0`, {
77	      fontFamily: 'system-ui, sans-serif',
78	      fontSize: '26px',
79	      fontStyle: 'bold',
80	      color: '#20272e',
81	    });
82	
83	    // Hearts (top-left, under the score) — Phase 1 shows all full.
84	    for (let i = 0; i < MAX_HP; i++) {
85	      this.add.image(42 + i * 44, 74, KEYS.ui_heart_full);
86	    }
87	
88	    // Full-width thin progress bar across the very top.
89	    this.add.rectangle(GAME_WIDTH / 2, 8, GAME_WIDTH - 40, 10, 0x2b3a46);
90	    this.progressFill = this.add
91	      .rectangle(20, 8, GAME_WIDTH - 40, 10, 0x6cc04a)
92	      .setOrigin(0, 0.5);
93	    this.progressFill.scaleX = 0;
94	  }
95	
96	  private buildDebugFinishControls(): void {
97	    this.add
98	      .text(GAME_WIDTH / 2, GAME_HEIGHT - 98, t('game_debug_hint'), {
99	        fontFamily: 'system-ui, sans-serif',
100	        fontSize: '16px',
101	        color: '#20272e',
102	      })
103	      .setOrigin(0.5);
104	
105	    createButton(this, {
106	      x: GAME_WIDTH / 2 - 135,
107	      y: GAME_HEIGHT - 50,
108	      width: 240,
109	      height: 56,
110	      label: t('game_debug_win'),
111	      onClick: () => this.finishRun('win'),
112	    });
113	    createButton(this, {
114	      x: GAME_WIDTH / 2 + 135,
115	      y: GAME_HEIGHT - 50,
116	      width: 240,
117	      height: 56,
118	      label: t('game_debug_lose'),
119	      onClick: () => this.finishRun('lose'),
120	    });
121	
122	    const kb = this.input.keyboard;
123	    kb?.addKey(Phaser.Input.Keyboard.KeyCodes.W).on('down', () => this.finishRun('win'));
124	    kb?.addKey(Phaser.Input.Keyboard.KeyCodes.L).on('down', () => this.finishRun('lose'));
125	  }
126	
127	  private onUpdate(_time: number, delta: number): void {
128	    if (this.finished) return;
129	
130	    this.elapsedMs += delta;
131	    const seconds = this.elapsedMs / 1000;
132	
133	    this.score = Math.floor(seconds * SCORE_SURVIVAL_PER_S);
134	    this.scoreText.setText(`${t('hud_score')}: ${this.score}`);
135	
136	    const progress = Phaser.Math.Clamp(seconds / TARGET_DURATION_S.nominal, 0, 1);
137	    this.progressFill.scaleX = progress;
138	  }
139	
140	  private finishRun(result: 'win' | 'lose'): void {
141	    if (this.finished) return;
142	    this.finished = true;
143	
144	    const payload: FinishGameParams = {
145	      result,
146	      score: this.score,
147	      duration_s: Math.round(this.elapsedMs / 1000),
148	    };
149	    track('finish_game', payload);
150	    this.scene.start(SceneKey.Results, payload);
151	  }
152	}
