1	import Phaser from 'phaser';
2	import { SceneKey } from './keys';
3	import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
4	import { KEYS } from '../config/assetManifest';
5	import { t } from '../i18n/strings';
6	import { track, type FinishGameParams } from '../analytics/track';
7	import { createButton } from '../ui/Button';
8	import { ENV, buildBuyUrl, buyDestination } from '../config/env';
9	
10	/**
11	 * ResultsScene — Victory or Game Over depending on the `result` param, the final
12	 * score, the promo-code chip, the buy CTA (fires `click_buy` then opens the
13	 * UTM-tagged buy URL in a new tab), and Play-again (→ a fresh run).
14	 */
15	export class ResultsScene extends Phaser.Scene {
16	  constructor() {
17	    super({ key: SceneKey.Results });
18	  }
19	
20	  create(data: FinishGameParams): void {
21	    const win = data.result === 'win';
22	    const cx = GAME_WIDTH / 2;
23	
24	    this.add.image(cx, GAME_HEIGHT / 2, win ? KEYS.screen_bg_victory : KEYS.screen_bg_gameover);
25	    this.add.image(cx, 250, win ? KEYS.dog_victory : KEYS.dog_defeat);
26	
27	    this.add
28	      .text(cx, 90, win ? t('results_victory_title') : t('results_gameover_title'), {
29	        fontFamily: 'system-ui, sans-serif',
30	        fontSize: '48px',
31	        fontStyle: 'bold',
32	        color: '#20272e',
33	      })
34	      .setOrigin(0.5);
35	
36	    this.add
37	      .text(cx, 380, t('results_score', { score: data.score }), {
38	        fontFamily: 'system-ui, sans-serif',
39	        fontSize: '30px',
40	        color: '#20272e',
41	      })
42	      .setOrigin(0.5);
43	
44	    // Promo chip + code.
45	    this.add.image(cx, 460, KEYS.ui_promo_chip);
46	    this.add
47	      .text(cx, 460, `${t('results_promo_label')} ${ENV.promoCode}`, {
48	        fontFamily: 'monospace',
49	        fontSize: '26px',
50	        fontStyle: 'bold',
51	        color: '#20272e',
52	      })
53	      .setOrigin(0.5);
54	
55	    // The conversion CTA.
56	    createButton(this, {
57	      x: cx,
58	      y: 565,
59	      texture: KEYS.ui_btn_cta,
60	      label: t('results_cta'),
61	      onClick: () => this.onBuy(),
62	    });
63	
64	    // Secondary: play again → fresh run (a new start_game fires in GameScene).
65	    createButton(this, {
66	      x: cx,
67	      y: 660,
68	      texture: KEYS.ui_btn_play_again,
69	      label: t('results_play_again'),
70	      onClick: () => this.scene.start(SceneKey.Game),
71	    });
72	
73	    // Tertiary: back to the menu — closes the Boot→…→Results→Menu loop.
74	    this.add
75	      .text(90, 44, `← ${t('results_menu')}`, {
76	        fontFamily: 'system-ui, sans-serif',
77	        fontSize: '22px',
78	        color: '#20272e',
79	      })
80	      .setOrigin(0, 0.5)
81	      .setInteractive({ useHandCursor: true })
82	      .on(Phaser.Input.Events.POINTER_UP, () => this.scene.start(SceneKey.Menu));
83	  }
84	
85	  private onBuy(): void {
